adcs_quat_t normalized_sample;
adcs_status_t status;
double signed_dot;
double cos_sep;
double sep_rad;

/* Step 1: Validate pointers */
if (sample == NULL) {
    return ADCS_E_NULL;
}

if (accepted == NULL || separation_rad == NULL) {
    if (accepted != NULL) {
        accepted->w = 1.0;
        accepted->x = 0.0;
        accepted->y = 0.0;
        accepted->z = 0.0;
    }
    if (separation_rad != NULL) {
        *separation_rad = INFINITY;
    }
    return ADCS_E_NULL;
}

/* Step 2: Normalize sample */
status = adcs_quat_normalize(sample, &normalized_sample);
if (status != ADCS_OK) {
    return ADCS_E_DEGENERATE;
}

/* Step 3: Handle first vs subsequent samples */
if (!qc_state.initialized) {
    /* First sample: Canonicalize to non-negative scalar part */
    if (normalized_sample.w < 0.0) {
        normalized_sample.w = -normalized_sample.w;
        normalized_sample.x = -normalized_sample.x;
        normalized_sample.y = -normalized_sample.y;
        normalized_sample.z = -normalized_sample.z;
    }

    /* Initialize state */
    qc_state.initialized = 1;
    qc_state.previous = normalized_sample;

    /* Set outputs */
    *accepted = normalized_sample;
    *separation_rad = 0.0;
} else {
    /* Subsequent samples: Sign alignment */
    signed_dot = normalized_sample.w * qc_state.previous.w +
                 normalized_sample.x * qc_state.previous.x +
                 normalized_sample.y * qc_state.previous.y +
                 normalized_sample.z * qc_state.previous.z;

    if (signed_dot < 0.0) {
        normalized_sample.w = -normalized_sample.w;
        normalized_sample.x = -normalized_sample.x;
        normalized_sample.y = -normalized_sample.y;
        normalized_sample.z = -normalized_sample.z;
    }

    /* Calculate sign-invariant separation */
    cos_sep = fabs(signed_dot);

    /* Clamp for numerical stability */
    if (cos_sep > 1.0) {
        cos_sep = 1.0;
    }

    /* Separation angle = 2 * acos(|dot|) */
    sep_rad = 2.0 * acos(cos_sep);

    /* Update state and outputs */
    qc_state.previous = normalized_sample;
    *accepted = normalized_sample;
    *separation_rad = sep_rad;
}

return ADCS_OK;

