adcs_quat_t normalized_sample;
double abs_dot;
double sep;

// 1. Validate output pointers first. If either is NULL, return ADCS_E_NULL immediately.
if (accepted == NULL || separation_rad == NULL) {
    return ADCS_E_NULL;
}

// 2. Validate sample-> If NULL, write default values and return error.
if (sample == NULL) {
    *accepted = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    *separation_rad = INFINITY;
    return ADCS_E_NULL;
}

// 3. Normalize sample-> If degenerate, write default values and return error.
if (adcs_quat_normalize(sample, &normalized_sample) != ADCS_OK) {
    *accepted = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    *separation_rad = INFINITY;
    return ADCS_E_DEGENERATE;
}

// 4. Handle first sample: canonicalize to non-negative scalar part.
if (!qc_state.initialized) {
    if (normalized_sample.w < 0.0) {
        normalized_sample.w = -normalized_sample.w;
        normalized_sample.x = -normalized_sample.x;
        normalized_sample.y = -normalized_sample.y;
        normalized_sample.z = -normalized_sample.z;
    }

    *accepted = normalized_sample;
    qc_state.previous = normalized_sample;
    qc_state.initialized = 1;
    *separation_rad = 0.0;

    return ADCS_OK;
}

// 5. Handle subsequent samples: sign-align to history.
double dot = normalized_sample.w * qc_state.previous.w +
             normalized_sample.x * qc_state.previous.x +
             normalized_sample.y * qc_state.previous.y +
             normalized_sample.z * qc_state.previous.z;

adcs_quat_t aligned_sample = normalized_sample;

// If dot product is negative, flip signs to maintain continuity.
if (dot < 0.0) {
    aligned_sample.w = -aligned_sample.w;
    aligned_sample.x = -aligned_sample.x;
    aligned_sample.y = -aligned_sample.y;
    aligned_sample.z = -aligned_sample.z;
}

// 6. Calculate sign-invariant separation.
abs_dot = adcs_quat_abs_dot(&normalized_sample, &qc_state.previous);

// Clamp for numerical stability in acos
if (abs_dot > 1.0) abs_dot = 1.0;
if (abs_dot < -1.0) abs_dot = -1.0;

sep = acos(abs_dot);
*separation_rad = sep;

// 7. Update history and output.
*accepted = aligned_sample;
qc_state.previous = aligned_sample;

return ADCS_OK;

