        norm_sample.x = -norm_sample.x;
        norm_sample.y = -norm_sample.y;
        norm_sample.z = -norm_sample.z;
    }
    *accepted = norm_sample;
    *separation_rad = 0.0;
    qc_state.initialized = 1;
    qc_state.previous = *accepted;
    return ADCS_OK;
} else {
    adcs_quat_t *prev = &qc_state.previous;
    dot = norm_sample.w * prev->w + norm_sample.x * prev->x + norm_sample.y * prev->y + norm_sample.z * prev->z;
    if (dot < 0.0) {
