    *accepted = norm_sample;
    abs_dot = fabs(dot);
    if (abs_dot > 1.0) {
        abs_dot = 1.0;
    }
    if (abs_dot < 0.0) {
        abs_dot = 0.0;
    }
    *separation_rad = 2.0 * acos(abs_dot);
